(() => {
'use strict';
const APP={storageKey:'socialStudiesGrade9Term1_v3',passPercent:65,questionsPerExam:15,totalLessons:11,totalUnits:4,speechLanguage:'ar-EG'};
const $=id=>document.getElementById(id), $$=s=>Array.from(document.querySelectorAll(s));
const CURRICULUM=[{"id":"lesson1","number":1,"title":"موقع ومظاهر سطح قارات العالم الجديد","subtitle":"الموقع الجغرافي، المساحة، وأهم مظاهر السطح في أمريكا الشمالية وأمريكا الجنوبية.","intro":"يبدأ الدرس بتحديد المقصود بقارات العالم الجديد، ثم يربط بين الموقع والمساحة ومظاهر السطح والأنشطة البشرية.","keyIdea":"فهم الموقع والتضاريس لا يعتمد على حفظ أسماء الأماكن فقط؛ بل على معرفة كيف يؤثر المكان في المناخ والموارد والسكان والأنشطة.","visual":"🗺️","visualText":"خريطة مفاهيم: الموقع ← التضاريس ← الموارد ← السكان والأنشطة.","parts":[["الجزء الأول: المقصود بالعالم الجديد",["يقصد الكتاب بقارات العالم الجديد قارتي أمريكا الشمالية وأمريكا الجنوبية. وتظهر أهمية دراسة موقعهما في اتساع امتدادهما وتنوع البيئات الموجودة داخلهما.","عند قراءة الخريطة نحدد موقع القارة بالنسبة للمحيطات والقارات المجاورة، ثم نربط الموقع بما يترتب عليه من علاقات واتصالات وخصائص طبيعية وبشرية."]],["الجزء الثاني: الموقع والمساحة",["الموقع الجغرافي يوضح موضع المكان بالنسبة إلى اليابس والماء والظواهر المحيطة به. وتساعد معرفة الموقع على تفسير اختلاف المناخ والموارد والطرق التي يستغل بها الإنسان البيئة.","اتساع مساحة القارتين يعني تنوعًا كبيرًا في البيئات والموارد والتضاريس، لذلك لا يصح تعميم صفة طبيعية واحدة على جميع أجزاء القارة."]],["الجزء الثالث: مظاهر السطح",["تتنوع مظاهر السطح في قارات العالم الجديد بين السلاسل الجبلية والهضاب والسهول والأحواض. ويؤدي اختلاف التضاريس إلى اختلاف ظروف الاستقرار والنقل واستغلال الموارد.","تساعد الخريطة الطبيعية على التمييز بين مناطق الارتفاع والانخفاض، كما تساعد الصور والرسوم في تصور شكل التضاريس بدل الاكتفاء باسمها."]],["الجزء الرابع: أثر السطح في الإنسان",["تؤثر التضاريس في توزيع السكان؛ فبعض المناطق السهلية تكون أنسب للزراعة والعمران ووسائل النقل، بينما تفرض المناطق الجبلية تحديات مختلفة على الحركة والاستقرار.","الهدف من دراسة الموقع ومظاهر السطح هو الوصول إلى علاقة متكاملة بين المكان والموارد والإنسان، وفهم سبب تنوع الأنشطة والبيئات داخل القارتين."]]],"terms":[["الموقع الجغرافي","موضع المكان بالنسبة إلى اليابس والمياه والظواهر المحيطة."],["قارات العالم الجديد","أمريكا الشمالية وأمريكا الجنوبية في سياق المنهج."],["التضاريس","أشكال سطح الأرض مثل الجبال والهضاب والسهول."],["السهول","أراضٍ أقل ارتفاعًا وانبساطًا نسبيًا، وتختلف ملاءمتها للأنشطة حسب البيئة."],["الهضاب","مناطق مرتفعة نسبيًا عن سطح البحر وتختلف أشكالها وامتداداتها."]],"quick":[["ما المقصود بقارات العالم الجديد؟","يقصد بها في هذا الدرس أمريكا الشمالية وأمريكا الجنوبية."],["لماذا نهتم بالموقع الجغرافي؟","لأنه يساعد على تفسير الخصائص الطبيعية والبشرية للمكان."],["اذكر أمثلة لمظاهر السطح.","الجبال والهضاب والسهول والأحواض."],["كيف يمكن أن تؤثر التضاريس في السكان؟","تؤثر في ملاءمة المناطق للعمران والزراعة والنقل، ومن ثم في توزيع السكان."],["ما فائدة الخريطة الطبيعية؟","تساعد على قراءة مواقع التضاريس والارتفاعات وتوزيعها."]],"exam":[["mc","ما القارتان المقصودتان بالعالم الجديد في المنهج؟",["أمريكا الشمالية وأمريكا الجنوبية","أوروبا وآسيا","أفريقيا وأوروبا","آسيا وأفريقيا"],0],["tf","الموقع الجغرافي يساعد على تفسير بعض خصائص المكان.",["صح","خطأ"],0],["mc","أي مما يلي من مظاهر السطح؟",["الجبال والهضاب والسهول","اللغات والعملات","العادات والتقاليد","المؤسسات السياسية"],0],["tf","تتسم جميع أجزاء قارات العالم الجديد ببيئة طبيعية واحدة.",["صح","خطأ"],1],["mc","ما الأداة الأنسب لقراءة توزيع التضاريس؟",["الخريطة الطبيعية","جدول الحصص","قائمة الأسماء","الميزانية"],0],["tf","قد تؤثر التضاريس في طرق النقل والاستقرار.",["صح","خطأ"],0],["mc","دراسة الموقع تفيد في فهم العلاقة بين المكان و...",["المناخ والموارد والأنشطة","ألوان الملابس فقط","عدد المدارس فقط","أسماء السكان فقط"],0],["tf","السهول والهضاب والجبال تمثل أنواعًا من مظاهر السطح.",["صح","خطأ"],0],["mc","من النتائج المحتملة لاختلاف التضاريس...",["تنوع البيئات والأنشطة","اختفاء الموارد تمامًا","تساوي كل المناطق","انعدام النقل في كل مكان"],0],["tf","يمكن أن تساعد الصور الجغرافية في تصور أشكال سطح الأرض.",["صح","خطأ"],0],["mc","لماذا لا يصح تعميم صفة طبيعية واحدة على القارة؟",["لاتساعها وتنوع بيئاتها","لأنها بلا تضاريس","لأنها بلا موارد","لأنها صغيرة جدًا"],0],["tf","الموقع والمساحة لا علاقة لهما بفهم تنوع البيئات.",["صح","خطأ"],1],["mc","من أمثلة الأنشطة التي تتأثر بالتضاريس...",["الزراعة والنقل والعمران","اللغة فقط","الأسماء فقط","الملابس فقط"],0],["tf","الخريطة الطبيعية تساعد في تحديد مناطق الارتفاع والانخفاض.",["صح","خطأ"],0],["mc","ما الهدف الأوسع من دراسة الموقع ومظاهر السطح؟",["فهم علاقة المكان بالإنسان والموارد","حفظ الأسماء دون فهم","إلغاء دور الخرائط","دراسة السكان فقط"],0]]},{"id":"lesson2","number":2,"title":"الحضارات القديمة في الأمريكتين","subtitle":"المايا والأزتك والإنكا وعلاقة الحضارات بالبيئة والإنسان.","intro":"يتناول الدرس نماذج من الحضارات القديمة في الأمريكتين، وكيف استطاعت المجتمعات تنظيم حياتها والاستفادة من بيئاتها.","keyIdea":"الحضارة نتيجة تفاعل الإنسان مع بيئته وتنظيمه لموارده ومعارفه ومجتمعه.","visual":"🏛️","visualText":"بطاقات تفاعلية للحضارات: المايا – الأزتك – الإنكا.","parts":[["الجزء الأول: الحضارة والبيئة",["نشأت في الأمريكتين حضارات قديمة متعددة، ومن أشهر الأسماء التي يركز عليها المنهج المايا والأزتك والإنكا. وقد اختلفت البيئات التي ظهرت فيها هذه الحضارات.","لا تنفصل دراسة الحضارة عن البيئة؛ فالمياه والتربة والتضاريس والموارد المتاحة تساعد في تفسير بعض أنماط الزراعة والاستقرار والعمران."]],["الجزء الثاني: حضارة المايا",["ارتبطت حضارة المايا بمناطق من أمريكا الوسطى، وظهرت فيها مجتمعات منظمة واهتمت بالزراعة والعمران والمعرفة.","توضح دراسة المايا أن الإنسان يستطيع التكيف مع البيئة وتطوير أساليب للعيش والإنتاج، وأن الحضارة تشمل جوانب مادية وفكرية وتنظيمية."]],["الجزء الثالث: الأزتك والإنكا",["ارتبط الأزتك بمنطقة وسط المكسيك، بينما قامت دولة الإنكا في مناطق من غرب أمريكا الجنوبية. ويظهر اختلاف الموقع كيف تنوعت البيئات التي عاشت فيها المجتمعات القديمة.","دراسة الحضارتين تركز على التنظيم واستغلال الموارد وتطوير أساليب للحياة، مع الانتباه إلى أن لكل حضارة ظروفها ومجالها الجغرافي الخاص."]],["الجزء الرابع: مقارنة وفهم",["يمكن مقارنة الحضارات من خلال الموقع والبيئة والموارد وأساليب التنظيم والإنجازات. والمقارنة الجيدة لا تكتفي بذكر الأسماء، بل توضح أوجه التشابه والاختلاف.","تساعد دراسة حضارات الأمريكتين على إدراك تنوع التجارب الإنسانية، كما تتيح المقارنة العامة مع الحضارات القديمة الأخرى دون الخلط بين الأماكن والأزمنة."]]],"terms":[["حضارة المايا","حضارة قديمة ارتبطت بمناطق من أمريكا الوسطى."],["الأزتك","حضارة قديمة ارتبطت بمنطقة وسط المكسيك."],["الإنكا","حضارة قديمة قامت في مناطق من غرب أمريكا الجنوبية."],["الحضارة","نمط متكامل من تنظيم المجتمع والمعرفة والعمران واستغلال الموارد."],["البيئة","مجموعة الظروف والموارد الطبيعية التي يعيش الإنسان ويتفاعل معها."]],"quick":[["اذكر ثلاث حضارات قديمة في الأمريكتين.","المايا والأزتك والإنكا."],["أين ارتبطت المايا؟","بمناطق من أمريكا الوسطى."],["بماذا ارتبط الأزتك؟","بمنطقة وسط المكسيك."],["بماذا ارتبطت الإنكا؟","بمناطق من غرب أمريكا الجنوبية."],["لماذا نقارن الحضارات؟","لفهم أوجه التشابه والاختلاف وعلاقة الإنسان بالبيئة والتنظيم والمعرفة."]],"exam":[["mc","أي مجموعة تضم حضارات قديمة في الأمريكتين؟",["المايا والأزتك والإنكا","الرومان والفرس والبابليون","الإغريق والرومان فقط","الفراعنة فقط"],0],["tf","اختلفت البيئات التي نشأت فيها الحضارات القديمة في الأمريكتين.",["صح","خطأ"],0],["mc","ارتبطت حضارة المايا بمناطق من...",["أمريكا الوسطى","شمال أوروبا","شرق آسيا","شمال أفريقيا"],0],["mc","ارتبط الأزتك بمنطقة...",["وسط المكسيك","شمال الهند","جنوب أوروبا","شرق أفريقيا"],0],["tf","البيئة لا تؤثر في أساليب معيشة الإنسان.",["صح","خطأ"],1],["mc","من جوانب دراسة الحضارة...",["التنظيم والعمران والمعرفة واستغلال الموارد","الأسماء فقط","اللغة فقط","العملة فقط"],0],["mc","ارتبطت دولة الإنكا بمناطق من...",["غرب أمريكا الجنوبية","غرب أوروبا","شرق آسيا","شمال أفريقيا"],0],["tf","يمكن أن تختلف الحضارات في أساليب تنظيم المجتمع.",["صح","خطأ"],0],["mc","تساعد المقارنة بين الحضارات على...",["فهم أوجه التشابه والاختلاف","إلغاء الاختلافات","تجاهل البيئة","حفظ الأسماء فقط"],0],["tf","الزراعة والعمران من المجالات التي يمكن أن ترتبط بالبيئة.",["صح","خطأ"],0],["mc","ما الذي يجعل دراسة الحضارة أوسع من حفظ اسمها؟",["ربطها بالموقع والبيئة والتنظيم والإنجازات","حفظ الاسم فقط","حذف الموقع","إهمال الإنسان"],0],["tf","دراسة الحضارات تساعد على فهم تنوع التجارب الإنسانية.",["صح","خطأ"],0],["mc","أي حضارة ارتبطت بوسط المكسيك؟",["الأزتك","الإنكا","المايا فقط","لا شيء مما سبق"],0],["mc","أي حضارة ارتبطت بمناطق من غرب أمريكا الجنوبية؟",["الإنكا","الأزتك","المايا","الرومان"],0],["tf","المايا والأزتك والإنكا حضارات من قارات العالم الجديد القديمة.",["صح","خطأ"],0]]},{"id":"lesson3","number":3,"title":"الكشوف الجغرافية لقارات العالم الجديد","subtitle":"دوافع الكشوف الجغرافية، الرحلات، دور العلماء المسلمين، والنتائج.","intro":"يفسر الدرس لماذا اتجهت الدول الأوروبية إلى الرحلات البحرية، وكيف توسعت معرفة العالم وما ترتب على ذلك من نتائج.","keyIdea":"الكشوف الجغرافية غيرت معرفة الناس بالعالم وربطت القارات، وكانت لها نتائج اقتصادية وسياسية وإنسانية متباينة.","visual":"⛵","visualText":"مسار تفاعلي: الدوافع → الرحلات → اكتشافات → نتائج.","parts":[["الجزء الأول: لماذا بدأت الكشوف؟",["من أهم دوافع الكشوف الجغرافية البحث عن طرق بحرية وتجارية جديدة، والوصول إلى مصادر الثروة، وزيادة النفوذ والتنافس بين الدول الأوروبية.","ساعد تطور المعرفة الجغرافية ووسائل الملاحة على تنفيذ رحلات بحرية لمسافات بعيدة، وأصبح البحر طريقًا رئيسيًا للبحث والاستكشاف."]],["الجزء الثاني: المعرفة والرحلات",["لم تبدأ المعرفة الجغرافية الأوروبية من فراغ؛ فقد استفادت أوروبا من تراث علمي وجغرافي سابق، ومن إسهامات علماء ورحالة مسلمين في وصف البلاد والطرق والبحار.","ساهمت الرحلات في اتساع الخرائط والمعرفة بالمحيطات والسواحل والمناطق الجديدة، وأصبحت المعلومات الجغرافية أداة مهمة في الرحلات والتجارة."]],["الجزء الثالث: العالم الجديد والاتصال",["أدت الرحلات إلى وصول الأوروبيين إلى مناطق في الأمريكتين، ثم توسعت حركة الاتصال والتجارة والهجرة بين أجزاء من العالم.","أصبح هناك انتقال واسع للسلع والنباتات والحيوانات والأفكار، وهو ما جعل الكشوف نقطة تحول في العلاقات بين القارات."]],["الجزء الرابع: النتائج والجانب الإنساني",["كانت للكشوف نتائج اقتصادية وسياسية، منها اتساع التجارة وبناء نفوذ استعماري أوروبي في مناطق مختلفة. وفي المقابل تعرض كثير من السكان الأصليين لأضرار وصراعات وفقدان للسيطرة على أراضيهم.","لذلك ينبغي دراسة الكشوف بصورة متوازنة: فهي وسعت المعرفة والاتصال، لكنها ارتبطت أيضًا بالاستعمار وآثار كبيرة على الشعوب الأصلية."]]],"terms":[["الكشوف الجغرافية","رحلات بحرية ساعدت على توسيع معرفة الأوروبيين بالمناطق والطرق."],["الدوافع","الأسباب التي دفعت الدول والرحالة إلى القيام بالرحلات."],["الملاحة","مهارات ووسائل تحديد الاتجاهات والمسارات في البحر."],["السكان الأصليون","الشعوب التي كانت تعيش في الأمريكتين قبل الاستعمار الأوروبي."],["الاستعمار","فرض دولة نفوذها وسيطرتها على أرض أو شعب خارج حدودها."]],"quick":[["اذكر دافعين للكشوف.","البحث عن طرق تجارية جديدة والوصول إلى الثروة والتنافس بين الدول الأوروبية."],["ما دور العلماء المسلمين في موضوع الكشوف؟","أسهموا في التراث الجغرافي ووصف البلاد والطرق والبحار، الذي استفادت منه المعرفة اللاحقة."],["ما نتيجة مهمة للرحلات؟","توسعت المعرفة بالخرائط والمحيطات والسواحل."],["ماذا انتقل بين القارات؟","سلع وأفكار ونباتات وحيوانات وغيرها."],["لماذا ندرس أثر الكشوف على السكان الأصليين؟","لفهم الجانب الإنساني والاستعماري من نتائج الكشوف."]],"exam":[["mc","أي مما يلي من دوافع الكشوف الجغرافية؟",["البحث عن طرق تجارية جديدة","منع الملاحة","إيقاف التجارة","إلغاء الرحلات"],0],["tf","ساهمت المعرفة الجغرافية والملاحة في نجاح الرحلات البحرية.",["صح","خطأ"],0],["mc","استفادت المعرفة الأوروبية من تراث جغرافي...",["قديم ومنه إسهامات علماء مسلمين","منعزل تمامًا","لا علاقة له بالرحلات","معدوم تمامًا"],0],["tf","لم يكن للتنافس بين الدول الأوروبية علاقة بالكشوف.",["صح","خطأ"],1],["mc","من نتائج الرحلات البحرية...",["اتساع الخرائط والمعرفة","اختفاء الخرائط","انقطاع التجارة","إلغاء الاتصال"],0],["tf","أدت الكشوف إلى زيادة الاتصال بين مناطق العالم.",["صح","خطأ"],0],["mc","ماذا نقصد بالسكان الأصليين؟",["الشعوب التي كانت تعيش في الأمريكتين قبل الاستعمار الأوروبي","المهاجرون الأوروبيون فقط","البحارة فقط","التجار فقط"],0],["tf","كان للكشوف نتائج اقتصادية وسياسية وإنسانية.",["صح","خطأ"],0],["mc","من النتائج الاقتصادية للكشوف...",["اتساع التجارة","إلغاء التجارة","توقف الملاحة","اختفاء الموانئ"],0],["tf","تعرضت شعوب أصلية لآثار سلبية مع التوسع الاستعماري.",["صح","خطأ"],0],["mc","ما أفضل طريقة لدراسة الكشوف؟",["دراسة الدوافع والرحلات والنتائج معًا","حفظ اسم واحد فقط","إهمال السكان","دراسة التجارة وحدها"],0],["tf","يمكن أن تنتقل النباتات والحيوانات بين القارات نتيجة الاتصال الجديد.",["صح","خطأ"],0],["mc","لماذا كانت الخرائط مهمة للرحلات؟",["لتحديد المواقع والمسارات بصورة أفضل","لمنع الإبحار","لإلغاء الاستكشاف","لتحديد الأسعار فقط"],0],["mc","أي نتيجة تمثل جانبًا سياسيًا؟",["اتساع النفوذ الاستعماري","زيادة المحاصيل فقط","تحسن الطقس","اختفاء الحدود"],0],["tf","الكشوف وسعت معرفة الأوروبيين بالمناطق والبحار.",["صح","خطأ"],0]]},{"id":"lesson4","number":4,"title":"تولية محمد علي حكم مصر وتثبيت دعائم حكمه","subtitle":"ظروف تولي محمد علي الحكم، ومراحل تثبيت سلطته وتنظيم الدولة.","intro":"يعرض الدرس بداية حكم محمد علي في مصر والظروف السياسية التي أحاطت به، ثم خطوات تثبيت الحكم.","keyIdea":"استقرار السلطة وتنظيم الإدارة كانا مقدمة لتنفيذ مشروع الإصلاح وبناء الدولة.","visual":"🏰","visualText":"خط زمني: تولي الحكم → تثبيت السلطة → تنظيم الإدارة → بداية الإصلاح.","parts":[["الجزء الأول: ظروف تولي الحكم",["وصل محمد علي إلى مصر ضمن الظروف التي أعقبت الحملة الفرنسية والصراع على السلطة، ثم أصبح واليًا على مصر سنة 1805م بعد تأييد قوى مصرية له وصدور القرار العثماني بتوليته.","كان تولي الحكم بداية مرحلة جديدة؛ إذ واجه الحاكم واقعًا سياسيًا معقدًا وتعددًا في مراكز القوة، ولذلك احتاج إلى تدعيم سلطته قبل تنفيذ مشروعه الإصلاحي."]],["الجزء الثاني: تثبيت السلطة",["عمل محمد علي على تقوية سلطته المركزية والحد من نفوذ القوى التي يمكن أن تنافس الحكم، مع إعادة ترتيب الإدارة والجيش بما يسمح بفرض النظام.","لم يكن تثبيت الحكم هدفًا منفصلًا عن الإصلاح؛ فقد كان وسيلة لتوفير الاستقرار والقدرة على تنفيذ سياسات الدولة في المجالات المختلفة."]],["الجزء الثالث: تنظيم الإدارة",["اعتمد بناء السلطة على تنظيم شؤون الإدارة والموارد والجيش، بحيث تصبح للدولة قدرة أكبر على جمع الموارد وتنفيذ القرارات ومتابعة الأقاليم.","كلما أصبحت الإدارة أكثر تنظيمًا أمكن للحاكم تنفيذ مشروعاته بصورة أوسع، ولهذا ارتبطت مرحلة تثبيت الحكم بمرحلة بناء الدولة."]],["الجزء الرابع: تمهيد الدولة الحديثة",["بعد تدعيم السلطة بدأت الإصلاحات تتجه إلى الجيش والاقتصاد والتعليم وغيرها من المجالات. ويظهر هنا تسلسل واضح: تثبيت الحكم ثم بناء المؤسسات ثم توسيع الإصلاح.","دراسة هذه المرحلة تساعد على فهم لماذا لم تبدأ كل الإصلاحات في وقت واحد، ولماذا كان الاستقرار السياسي والإداري مهمًا لنجاح مشروع محمد علي."]]],"terms":[["محمد علي","حاكم مصر الذي بدأ مشروعًا واسعًا لبناء دولة حديثة في القرن التاسع عشر."],["تثبيت دعائم الحكم","تقوية السلطة وتنظيم الإدارة والحد من مراكز القوى المنافسة."],["السلطة المركزية","سلطة قادرة على إصدار القرارات وتطبيقها على نطاق الدولة."],["الإدارة","تنظيم شؤون الدولة والأقاليم وتنفيذ القرارات."],["الحملة الفرنسية","الحملة التي سبقت مرحلة تولي محمد علي وارتبطت بتحولات سياسية في مصر."]],"quick":[["متى تولى محمد علي حكم مصر؟","تولى الحكم سنة 1805م."],["لماذا احتاج إلى تثبيت سلطته؟","بسبب تعقد الأوضاع وتعدد مراكز القوى والحاجة إلى سلطة مستقرة."],["ما المقصود بتثبيت دعائم الحكم؟","تقوية السلطة وتنظيم الإدارة والحد من القوى المنافسة."],["كيف مهد تثبيت الحكم للإصلاح؟","وفر استقرارًا وقدرة على تنفيذ السياسات والمشروعات."],["ما المجالات التي اتجه إليها الإصلاح بعد ذلك؟","الجيش والاقتصاد والتعليم والإدارة وغيرها."]],"exam":[["mc","في أي عام تولى محمد علي حكم مصر؟",["1805م","1798م","1840م","1882م"],0],["tf","ارتبط تولي محمد علي بظروف سياسية معقدة في مصر.",["صح","خطأ"],0],["mc","كان تثبيت الحكم مهمًا لأنه...",["وفر سلطة مستقرة لتنفيذ الإصلاح","أوقف الإدارة","ألغى الدولة","منع تنظيم الجيش"],0],["tf","كان تعدد مراكز القوى من التحديات السياسية.",["صح","خطأ"],0],["mc","ماذا يعني تثبيت دعائم الحكم؟",["تقوية السلطة وتنظيم الإدارة","إلغاء الإدارة","إيقاف الموارد","ترك الأقاليم بلا تنظيم"],0],["tf","تنظيم الإدارة يساعد الدولة على تنفيذ القرارات.",["صح","خطأ"],0],["mc","ما الذي جاء بعد تدعيم السلطة ضمن المشروع؟",["توسيع الإصلاح وبناء الدولة","إلغاء التعليم","إيقاف الجيش","منع الإنتاج"],0],["tf","كان الاستقرار السياسي منفصلًا تمامًا عن الإصلاح.",["صح","خطأ"],1],["mc","أي مجال أصبح من مجالات الإصلاح اللاحقة؟",["الجيش والتعليم والاقتصاد","الأسماء فقط","الملابس فقط","الطقس فقط"],0],["tf","ارتبط بناء الدولة الحديثة بتنظيم المؤسسات والإدارة.",["صح","خطأ"],0],["mc","ما العلاقة بين تثبيت الحكم وبناء الدولة؟",["الأول مهّد للثاني","لا علاقة بينهما","الثاني منع الأول","الأول ألغى الدولة"],0],["tf","كان هدف تنظيم الإدارة زيادة قدرة الدولة على تنفيذ قراراتها.",["صح","خطأ"],0],["mc","ما أهمية دراسة ظروف تولي محمد علي؟",["لفهم بداية مشروعه السياسي والإصلاحي","لحفظ التاريخ دون سياق","لتجاهل الإصلاح","لإلغاء دور الإدارة"],0],["mc","أي ترتيب يعبر عن تسلسل منطقي؟",["تولي الحكم ثم تثبيت السلطة ثم الإصلاح","الإصلاح ثم تولي الحكم ثم الفوضى","التعليم ثم تولي الحكم ثم تثبيت السلطة","الاحتلال ثم تولي الحكم"],0],["tf","بدأ مشروع الدولة الحديثة في سياق من إعادة تنظيم السلطة.",["صح","خطأ"],0]]},{"id":"lesson5","number":5,"title":"محمد علي وبناء الدولة الحديثة في مصر","subtitle":"الجيش والاقتصاد والتعليم والعمران والسياسة الخارجية.","intro":"يركز الدرس على مشروع محمد علي في تحويل مصر إلى دولة أكثر تنظيمًا من خلال إصلاحات متعددة.","keyIdea":"قوة الدولة الحديثة اعتمدت على ترابط الجيش والاقتصاد والتعليم والإدارة والعمران، مع ارتباط السياسة الخارجية بأهداف الدولة.","visual":"🏭","visualText":"خريطة ترابط: الجيش ↔ الاقتصاد ↔ التعليم ↔ العمران ↔ الإدارة.","parts":[["الجزء الأول: إصلاح الجيش",["اهتم محمد علي بتكوين جيش أكثر تنظيمًا وتدريبًا، لأن الجيش كان عنصرًا أساسيًا في حماية الدولة ودعم السلطة وتنفيذ سياستها.","ارتبط الإصلاح العسكري بالتعليم والتدريب والتنظيم، وأصبح إعداد الكوادر جزءًا من مشروع بناء الدولة."]],["الجزء الثاني: الاقتصاد والاحتكار",["اتجهت الدولة إلى تنظيم الزراعة والتجارة والإنتاج، وربطت جانبًا من النشاط الاقتصادي بسياسة الاحتكار؛ أي سيطرة الدولة على شراء بعض المحاصيل وبيعها أو تنظيم تجارتها لتحقيق موارد للدولة.","ساعدت هذه السياسة على توفير موارد لتمويل الجيش والإدارة والمشروعات، لكنها جعلت الدولة طرفًا قويًا في النشاط الاقتصادي."]],["الجزء الثالث: التعليم والعمران",["اهتم محمد علي بالتعليم وإعداد المتخصصين، وأرسل بعثات للاستفادة من الخبرات الحديثة، وأنشأ مؤسسات تعليمية تخدم احتياجات الدولة.","كما شهدت البلاد أعمالًا عمرانية وزراعية، وارتبط تطوير الري والزراعة بزيادة الإنتاج وتوفير الموارد للمشروع الاقتصادي."]],["الجزء الرابع: السياسة الخارجية ونهاية مرحلة القوة",["امتد مشروع محمد علي إلى خارج مصر، وارتبط بالصراع على النفوذ داخل الدولة العثمانية وبالتوسع في مناطق مجاورة. ومع اتساع نفوذه تدخلت القوى الأوروبية.","أدت الضغوط الأوروبية إلى تسوية سنة 1840م عُرفت بمعاهدة لندن، وتراجعت بعدها طموحات محمد علي الخارجية، مع بقاء جانب مهم من إصلاحاته داخل مصر."]]],"terms":[["الاحتكار","تنظيم الدولة لشراء أو بيع بعض المنتجات والسيطرة على جانب من التجارة."],["البعثات","إرسال طلاب أو متعلمين إلى الخارج لاكتساب خبرات ومعارف."],["الإصلاح العسكري","تطوير الجيش من حيث التدريب والتنظيم والتسليح والكوادر."],["العمران","أعمال ومشروعات مرتبطة بتنظيم المدن والمنشآت والطرق وغيرها."],["معاهدة لندن 1840","تسوية دولية أدت إلى تراجع التوسع الخارجي لمحمد علي."]],"quick":[["لماذا اهتم محمد علي بالجيش؟","لأنه كان عنصرًا أساسيًا في حماية الدولة ودعم السلطة."],["ما المقصود بالاحتكار؟","تنظيم الدولة لجزء من شراء وبيع المنتجات والتجارة."],["لماذا اهتم بالتعليم والبعثات؟","لإعداد المتخصصين ونقل الخبرات الحديثة."],["كيف ارتبط الري بالاقتصاد؟","تطوير الري ساعد الزراعة والإنتاج وتوفير الموارد."],["ماذا حدث سنة 1840م؟","تمت تسوية دولية في معاهدة لندن حدّت من التوسع الخارجي لمحمد علي."]],"exam":[["mc","ما الهدف الأساسي من إصلاح الجيش؟",["تقوية الدولة وتنظيم قواتها","إلغاء الإدارة","وقف التعليم","منع الإنتاج"],0],["tf","ارتبط إصلاح الجيش بالتدريب والتنظيم.",["صح","خطأ"],0],["mc","ماذا تعني سياسة الاحتكار في هذا السياق؟",["تنظيم الدولة جانبًا من شراء وبيع المنتجات","إلغاء التجارة تمامًا","ترك كل الإنتاج بلا تنظيم","منع الزراعة"],0],["tf","وفرت السياسة الاقتصادية موارد لتمويل بعض احتياجات الدولة.",["صح","خطأ"],0],["mc","لماذا أنشئت مؤسسات تعليمية وأرسلت بعثات؟",["لإعداد المتخصصين ونقل الخبرات","لمنع التعليم","لإيقاف الجيش","لإلغاء الإدارة"],0],["tf","ارتبط تطوير الري بالزراعة والإنتاج.",["صح","خطأ"],0],["mc","أي المجالات التالية كان جزءًا من بناء الدولة الحديثة؟",["التعليم والعمران","الأسماء فقط","الملابس فقط","الترفيه فقط"],0],["tf","لم يكن للاقتصاد علاقة بتمويل مشروعات الدولة.",["صح","خطأ"],1],["mc","ما الذي حد من طموحات محمد علي الخارجية سنة 1840م؟",["معاهدة لندن والضغط الأوروبي","زيادة الإنتاج الزراعي","التعليم","تطوير الري"],0],["tf","ارتبطت السياسة الخارجية لمحمد علي بالصراع على النفوذ.",["صح","خطأ"],0],["mc","ما العلاقة بين التعليم والجيش؟",["التعليم ساعد في إعداد الكوادر اللازمة للدولة","لا علاقة إطلاقًا","التعليم أوقف التدريب","الجيش ألغى التعليم"],0],["tf","كان مشروع محمد علي قائمًا على مجال واحد فقط.",["صح","خطأ"],1],["mc","أي عبارة أدق عن الإصلاحات؟",["كانت مترابطة لخدمة بناء الدولة","كانت منفصلة بلا هدف","اقتصرت على الزراعة","اقتصرت على الجيش"],0],["mc","ما الأثر المباشر لمعاهدة لندن 1840م؟",["تراجع التوسع الخارجي لمحمد علي","بدء الحملة الفرنسية","بدء الاحتلال البريطاني","إلغاء التعليم"],0],["tf","بقيت بعض آثار إصلاحات محمد علي داخل مصر رغم تراجع طموحاته الخارجية.",["صح","خطأ"],0]]},{"id":"lesson6","number":6,"title":"مصر في عصر خلفاء محمد علي","subtitle":"عباس حلمي الأول، محمد سعيد باشا، الخديو إسماعيل، الحركة الوطنية وأزمة الديون والتدخل الأجنبي.","intro":"يتتبع الدرس أحوال مصر في عهد خلفاء محمد علي حتى اتساع التدخل الأجنبي نتيجة أزمة الديون.","keyIdea":"اختلفت سياسات خلفاء محمد علي، وتداخلت مشروعات التحديث مع مشكلات مالية وسياسية انتهت بتزايد التدخل الأجنبي.","visual":"👑","visualText":"خط زمني: عباس حلمي الأول → سعيد باشا → إسماعيل → أزمة الديون والتدخل.","parts":[["الجزء الأول: عباس حلمي الأول",["جاء عباس حلمي الأول بعد مرحلة محمد علي، واتسم عهده بتراجع بعض جوانب مشروع التحديث مقارنة بما سبقه، مع اهتمام مختلف بأولويات الحكم.","يساعد التعرف على عهده في فهم أن مشروع الدولة لم يستمر بالوتيرة نفسها في كل الفترات، وأن السياسات تغيرت بتغير الحكام والظروف."]],["الجزء الثاني: محمد سعيد باشا",["ارتبط عهد محمد سعيد باشا بتغيرات في الإدارة والاقتصاد، وشهدت البلاد استمرار بعض المشروعات مع ظهور توجهات جديدة في التعامل مع التجارة والمشروعات.","توضح دراسة هذه المرحلة كيف تأثرت مصر بعلاقاتها الدولية وبالمشروعات المرتبطة بالمواصلات والتجارة، في وقت بدأت فيه مصالح الدول الأوروبية تزداد."]],["الجزء الثالث: الخديو إسماعيل والتحديث",["سعى الخديو إسماعيل إلى توسيع مشروعات التحديث والعمران والتعليم والمواصلات، واهتم بإظهار مصر في صورة دولة حديثة، وارتبط عهده بمشروعات كبرى.","شهد عهده أيضًا نشاطًا في الحركة الوطنية وازدياد النقاش حول أوضاع البلاد وحقوق المصريين، بينما احتاجت المشروعات إلى تمويل كبير."]],["الجزء الرابع: أزمة الديون والتدخل الأجنبي",["أدت كثرة الإنفاق والاقتراض وتراكم الالتزامات إلى أزمة مالية. ومع صعوبة سداد الديون زادت الضغوط الأوروبية على مصر، وظهر صندوق الدين وأشكال من الرقابة المالية.","تطورت الأزمة إلى تدخل أجنبي في شؤون الدولة، وهو ما أضعف استقلال القرار ومهّد لظروف سياسية انتهت لاحقًا بالاحتلال البريطاني."]]],"terms":[["عباس حلمي الأول","أحد خلفاء محمد علي وحكم مصر بعده."],["محمد سعيد باشا","أحد خلفاء محمد علي وارتبط عهده بتغيرات اقتصادية ومواصلات."],["الخديو إسماعيل","حاكم مصر الذي توسعت في عهده مشروعات التحديث والعمران."],["أزمة الديون","مشكلة مالية نتجت عن تراكم الالتزامات وصعوبة السداد."],["صندوق الدين","جهاز ارتبط بالرقابة على مالية مصر في ظل أزمة الديون."]],"quick":[["من أبرز خلفاء محمد علي؟","عباس حلمي الأول ومحمد سعيد باشا والخديو إسماعيل."],["ما الذي ميز عهد إسماعيل؟","توسع مشروعات التحديث والعمران والمواصلات والتعليم."],["ما سبب الأزمة المالية؟","تراكم الديون والالتزامات مع ارتفاع الإنفاق والحاجة إلى التمويل."],["ما أثر صندوق الدين؟","زيادة الرقابة الأجنبية على مالية مصر."],["إلى ماذا أدى التدخل المالي؟","إلى زيادة التدخل الأجنبي في شؤون مصر وإضعاف استقلال القرار."]],"exam":[["mc","أي حاكم ارتبط اسمه بتوسع مشروعات التحديث في مصر؟",["الخديو إسماعيل","عباس حلمي الأول فقط","محمد علي فقط","لا أحد"],0],["tf","اختلفت سياسات خلفاء محمد علي عن سياساته في بعض الفترات.",["صح","خطأ"],0],["mc","ما المشكلة التي أصبحت خطيرة في عهد إسماعيل؟",["أزمة الديون","اختفاء الزراعة","انعدام السكان","اختفاء التجارة"],0],["tf","كان للتحديث والمشروعات احتياجات مالية كبيرة.",["صح","خطأ"],0],["mc","ماذا يعني تراكم الديون؟",["زيادة الالتزامات وصعوبة السداد","اختفاء الالتزامات","زيادة الموارد بلا حدود","إلغاء القروض"],0],["tf","ارتبط صندوق الدين بالرقابة المالية على مصر.",["صح","خطأ"],0],["mc","من خلفاء محمد علي...",["عباس حلمي الأول ومحمد سعيد باشا","نابليون فقط","مصطفى كامل","محمد فريد"],0],["tf","لم تؤثر الديون في درجة التدخل الأجنبي.",["صح","خطأ"],1],["mc","أي مجال ارتبط بمشروعات إسماعيل؟",["العمران والمواصلات والتعليم","إلغاء التعليم","منع الطرق","إيقاف التجارة"],0],["tf","شهد عهد إسماعيل نشاطًا للحركة الوطنية.",["صح","خطأ"],0],["mc","ما نتيجة الضغوط المالية الأجنبية؟",["زيادة التدخل في شؤون مصر","زيادة الاستقلال المالي","إلغاء الديون فورًا","وقف التجارة العالمية"],0],["mc","ما العلاقة بين الاقتراض والتدخل الأجنبي؟",["صعوبة السداد فتحت مجالًا للرقابة والضغط","لا علاقة بينهما","الاقتراض أنهى التدخل","الاقتراض ألغى الديون"],0],["tf","أزمة الديون كانت مشكلة اقتصادية ذات آثار سياسية.",["صح","خطأ"],0],["mc","ما التسلسل الأقرب لأحداث الدرس؟",["مشروعات وتحديث → ديون → رقابة وتدخل","احتلال → تحديث → ديون","ثورة عرابية → ديون → إسماعيل","تعليم → استقلال مالي كامل"],0],["tf","ساعدت الأزمة المالية على إضعاف استقلال القرار المصري.",["صح","خطأ"],0]]},{"id":"lesson7","number":7,"title":"نظم الغابات والحشائش في قارات العالم الجديد","subtitle":"الغابات والحشائش وخصائصها وتوزيعها واستغلال الإنسان لها.","intro":"يتناول الدرس النظم البيئية التي تغطي مساحات من أمريكا الشمالية وأمريكا الجنوبية وعلاقتها بالمناخ والنشاط البشري.","keyIdea":"النبات الطبيعي يعكس ظروف البيئة، وخاصة الحرارة والأمطار، ويتأثر باستغلال الإنسان ودرجة حماية الموارد.","visual":"🌳","visualText":"مقارنة تفاعلية: غابات كثيفة ↔ حشائش واسعة.","parts":[["الجزء الأول: معنى النظام البيئي",["النظام البيئي يضم الكائنات الحية والعناصر غير الحية والعلاقات المتبادلة بينها. وتختلف النظم البيئية عندما تختلف الحرارة والأمطار والتربة والتضاريس.","تظهر الغابات والحشائش كنظم نباتية مهمة في قارات العالم الجديد، ويختلف توزيعها من منطقة إلى أخرى وفق الظروف الطبيعية."]],["الجزء الثاني: الغابات",["تنتشر أنواع مختلفة من الغابات في مناطق من القارتين، وتختلف كثافتها وخصائصها تبعًا لكمية الأمطار ودرجات الحرارة.","توفر الغابات موارد متعددة مثل الأخشاب والمنتجات النباتية، كما تؤدي دورًا بيئيًا في حماية التربة وتنظيم دورة المياه وتوفير موائل للكائنات."]],["الجزء الثالث: الحشائش",["تنتشر الحشائش في مناطق تقل فيها كثافة الأشجار أو تختلف فيها ظروف المطر والحرارة، وتتميز بارتباطها بأنشطة رعوية وزراعية في مناطق عديدة.","يمكن أن تكون الحشائش موردًا مهمًا للثروة الحيوانية، لكن الاستغلال الزائد والحرائق والتغيرات المناخية قد تؤثر في استدامتها."]],["الجزء الرابع: الإنسان والحماية",["يستفيد الإنسان من الغابات والحشائش، لكنه قد يسبب تدهورها عند قطع الأشجار بصورة غير مستدامة أو الرعي الجائر أو التوسع غير المنظم.","حماية النظم البيئية تحتاج إلى ترشيد الاستغلال وإنشاء مناطق محمية وإعادة التشجير ومواجهة مصادر التدهور."]]],"terms":[["النظام البيئي","كائنات حية وعناصر غير حية تتفاعل في مكان معين."],["الغابات","نظم نباتية يغلب عليها وجود الأشجار وتختلف حسب المناخ."],["الحشائش","نظم نباتية تكثر فيها الأعشاب وتقل كثافة الأشجار نسبيًا."],["التنوع الحيوي","تنوع الكائنات الحية في النظام البيئي."],["الرعي الجائر","استخدام المراعي بصورة تتجاوز قدرتها على التجدد."]],"quick":[["ما الذي يحدد اختلاف النظم البيئية؟","الحرارة والأمطار والتربة والتضاريس وغيرها."],["ما أهمية الغابات؟","توفر موارد وتدعم التنوع الحيوي وتحمي التربة وتشارك في دورة المياه."],["بماذا ترتبط الحشائش؟","بأنشطة الرعي والزراعة في مناطق مختلفة."],["كيف يضر الإنسان الغابات؟","بقطع الأشجار غير المستدام والتوسع غير المنظم وغيرها."],["اذكر وسيلة للحماية.","إعادة التشجير أو إنشاء المحميات وترشيد الاستغلال."]],"exam":[["mc","ما العاملان الأكثر ارتباطًا بتوزيع النبات الطبيعي؟",["الحرارة والأمطار","اللغة والعملة","عدد السكان فقط","الحدود السياسية فقط"],0],["tf","يضم النظام البيئي عناصر حية وغير حية.",["صح","خطأ"],0],["mc","من فوائد الغابات...",["حماية التربة وتوفير موائل وموارد","إلغاء التنوع الحيوي","منع دورة المياه","إيقاف الزراعة"],0],["tf","تتشابه جميع الغابات في الكثافة والخصائص.",["صح","خطأ"],1],["mc","ترتبط الحشائش في مناطق عديدة بـ...",["الرعي والزراعة","التعدين فقط","الملاحة فقط","الصناعة البحرية فقط"],0],["tf","يمكن أن يؤثر الرعي الجائر في المراعي.",["صح","خطأ"],0],["mc","أي نشاط يهدد الغابات؟",["القطع غير المستدام للأشجار","إعادة التشجير","الحماية","ترشيد الاستخدام"],0],["tf","يمكن للنبات الطبيعي أن يعكس ظروف المناخ.",["صح","خطأ"],0],["mc","ما المقصود بالتنوع الحيوي؟",["تنوع الكائنات الحية","تنوع العملات","تنوع الحدود","تنوع اللغات فقط"],0],["tf","إعادة التشجير وسيلة للمساعدة في حماية الغابات.",["صح","خطأ"],0],["mc","لماذا تختلف النظم النباتية بين المناطق؟",["لاختلاف الظروف الطبيعية","لأن جميع المناطق متشابهة","بسبب اللغة فقط","بسبب أسماء المدن"],0],["tf","الإنسان يستفيد من النظم البيئية ويمكن أن يؤثر فيها سلبًا.",["صح","خطأ"],0],["mc","ما الحل الأنسب للرعي؟",["ترشيد الرعي بما يحافظ على قدرة المراعي على التجدد","زيادة الرعي بلا حدود","إزالة الحشائش","إحراق المراعي"],0],["mc","أي وظيفة بيئية للغابات صحيحة؟",["توفير موائل والمساعدة في حماية التربة","منع المطر","إلغاء الكائنات","زيادة التصحر دائمًا"],0],["tf","حماية النظم البيئية تعني منع الإنسان من كل استخدام للموارد.",["صح","خطأ"],1]]},{"id":"lesson8","number":8,"title":"النظم الصحراوية والمائية في قارات العالم الجديد","subtitle":"الصحاري والمياه والتيارات البحرية وأهميتها.","intro":"يتناول الدرس النظم الصحراوية والمائية وعوامل تنوعها ودور المياه والتيارات البحرية في البيئة.","keyIdea":"المياه والتضاريس والتيارات البحرية عوامل أساسية في تشكيل النظم البيئية وتوزيع الأنشطة البشرية.","visual":"🏜️","visualText":"خريطة مفاهيم: صحاري + أنهار + بحيرات + سواحل + تيارات بحرية.","parts":[["الجزء الأول: النظم الصحراوية",["تظهر النظم الصحراوية في مناطق تقل فيها الأمطار وتزداد فيها ظروف الجفاف، وتختلف خصائصها حسب الحرارة والتضاريس والموارد المائية المتاحة.","تتكيف الكائنات في البيئات الصحراوية مع ندرة المياه، بينما يتركز السكان والأنشطة عادة حول مصادر المياه والمناطق الأكثر ملاءمة."]],["الجزء الثاني: النظم المائية",["تشمل النظم المائية الأنهار والبحيرات والمياه الساحلية والمحيطات، وتوفر المياه للشرب والزراعة والنقل والطاقة وتدعم كائنات حية كثيرة.","تختلف النظم المائية في خصائصها، لكن جميعها تحتاج إلى إدارة وحماية من التلوث والاستغلال غير الرشيد."]],["الجزء الثالث: التيارات البحرية",["التيارات البحرية حركة مستمرة نسبيًا لمياه البحر، ويمكن أن تؤثر في درجات الحرارة والرطوبة والظروف المناخية في المناطق الساحلية.","لذلك تساعد دراسة التيارات في تفسير بعض الاختلافات بين السواحل وفي فهم علاقة المحيطات بالمناخ والنشاط البشري."]],["الجزء الرابع: الإنسان وحماية المياه",["تعتمد مجتمعات كثيرة على المياه في الزراعة والصناعة والنقل والصيد، ولذلك يؤدي تلوثها أو استنزافها إلى أضرار بيئية واقتصادية.","الحماية تبدأ بترشيد الاستخدام، وتقليل مصادر التلوث، والحفاظ على السواحل والأنهار والبحيرات والموارد المائية."]]],"terms":[["النظام الصحراوي","نظام بيئي يغلب عليه الجفاف وندرة الأمطار."],["النظام المائي","نظام بيئي مرتبط بالمياه مثل الأنهار والبحيرات والمحيطات."],["التيارات البحرية","حركة منتظمة نسبيًا لمياه البحر تؤثر في البيئات الساحلية."],["الجفاف","حالة ترتبط بنقص المياه أو قلة الأمطار لفترات أو مناطق معينة."],["تلوث المياه","دخول مواد ضارة إلى المياه بما يؤثر في صلاحيتها والكائنات الحية."]],"quick":[["ما سبب ظهور البيئات الصحراوية؟","قلة الأمطار وزيادة ظروف الجفاف مع تأثير عوامل أخرى."],["لماذا تتركز بعض الأنشطة قرب المياه؟","لأن المياه ضرورية للزراعة والشرب والنقل وغيرها."],["ما أمثلة النظم المائية؟","الأنهار والبحيرات والمياه الساحلية والمحيطات."],["ما أثر التيارات البحرية؟","قد تؤثر في الحرارة والرطوبة والظروف المناخية للسواحل."],["كيف نحمي المياه؟","بترشيد الاستخدام وتقليل التلوث وحماية مصادر المياه."]],"exam":[["mc","ما السمة الأساسية للبيئة الصحراوية؟",["ندرة الأمطار والجفاف","غزارة الأمطار دائمًا","كثافة الغابات دائمًا","وفرة المياه السطحية في كل مكان"],0],["tf","توجد نظم مائية في الأنهار والبحيرات والمحيطات.",["صح","خطأ"],0],["mc","من استخدامات المياه...",["الشرب والزراعة والنقل","الزينة فقط","إيقاف الإنتاج","منع الصيد"],0],["tf","التيارات البحرية لا يمكن أن تؤثر في السواحل.",["صح","خطأ"],1],["mc","ما المقصود بالتيارات البحرية؟",["حركة منتظمة نسبيًا لمياه البحر","حركة الجبال","حركة السكان","حركة الرمال فقط"],0],["tf","يمكن أن تؤثر التيارات البحرية في درجات الحرارة الساحلية.",["صح","خطأ"],0],["mc","لماذا يزداد الاستقرار قرب مصادر المياه في مناطق جافة؟",["للحاجة إلى المياه","لعدم وجود أي نشاط","لأن الصحراء بلا سكان دائمًا","لأن الماء غير مهم"],0],["tf","تلوث المياه قد يضر الإنسان والكائنات الحية.",["صح","خطأ"],0],["mc","أي مما يلي مصدر مائي؟",["نهر","سهل","هضبة","جبل"],0],["tf","ترشيد استخدام المياه من وسائل الحماية.",["صح","خطأ"],0],["mc","ما العلاقة بين المياه والنشاط الاقتصادي؟",["المياه تدعم الزراعة والنقل والصناعة وغيرها","لا علاقة","المياه تمنع الزراعة","المياه تلغي النقل"],0],["tf","تختلف النظم الصحراوية حسب الحرارة والتضاريس وتوفر المياه.",["صح","خطأ"],0],["mc","ما الذي يجب تجنبه لحماية المياه؟",["إلقاء الملوثات في مصادر المياه","ترشيد الاستهلاك","معالجة التلوث","حماية السواحل"],0],["mc","ما أحد آثار التيارات البحرية؟",["التأثير في الظروف المناخية للسواحل","إلغاء المحيطات","تكوين الجبال","إيقاف الأمطار عالميًا"],0],["tf","حماية النظم المائية جزء من حماية البيئة.",["صح","خطأ"],0]]},{"id":"lesson9","number":9,"title":"التغير المناخي وتأثيره على النظم البيئية","subtitle":"مفهوم التغير المناخي وآثاره ودور الفرد في الحد منها.","intro":"يشرح الدرس التغير المناخي بوصفه تغيرًا طويل المدى في أنماط المناخ، ثم يربط آثاره بالنظم البيئية ودور الإنسان.","keyIdea":"التغير المناخي يؤثر في المياه والنبات والحيوان والأنشطة البشرية، ومواجهة آثاره تحتاج إلى تقليل الأسباب والتكيف مع النتائج.","visual":"🌡️","visualText":"مخطط تفاعلي: تغير المناخ → تغير المياه والنبات → آثار على الإنسان.","parts":[["الجزء الأول: مفهوم التغير المناخي",["التغير المناخي هو تغير طويل المدى في أنماط درجات الحرارة والأمطار وغيرها من عناصر المناخ. ويمكن أن تنتج التغيرات الحالية عن عوامل طبيعية وبشرية، مع أهمية زيادة تأثير الأنشطة البشرية في العصر الحديث.","ترتبط زيادة الغازات الدفيئة الناتجة عن حرق الوقود الأحفوري وتغير استخدامات الأرض بارتفاع الاحترار العالمي، وهو ما ينعكس على النظم البيئية."]],["الجزء الثاني: تأثيره في النظم البيئية",["قد تتغير مواسم الأمطار ودرجات الحرارة وتوافر المياه، مما يؤثر في النباتات والحيوانات وموائلها، وقد يزيد الضغط على بعض الأنظمة البيئية الحساسة.","تتعرض بعض المناطق لمخاطر مثل موجات الحرارة والجفاف والفيضانات والعواصف، وتختلف شدة الآثار من مكان إلى آخر حسب الظروف المحلية."]],["الجزء الثالث: الإنسان والاقتصاد",["تؤثر التغيرات المناخية في الزراعة والموارد المائية والصحة والبنية الأساسية، وقد ترفع تكلفة التعامل مع الكوارث وتغير أنماط الإنتاج.","تحتاج المجتمعات إلى التكيف، مثل تحسين إدارة المياه والاستعداد للمخاطر، وفي الوقت نفسه تقليل الانبعاثات التي تزيد الاحترار."]],["الجزء الرابع: دور الفرد",["يمكن للفرد المساهمة في الحد من الآثار عبر ترشيد استهلاك الطاقة والمياه، وتقليل الهدر، وزيادة استخدام وسائل النقل الأقل تلويثًا عندما تكون متاحة، وزراعة الأشجار وحماية المساحات الخضراء.","المواجهة مسؤولية مشتركة بين الأفراد والمؤسسات والدول؛ فالسلوك الفردي مهم، لكنه ينجح أكثر عندما تدعمه سياسات ومشروعات بيئية واسعة."]]],"terms":[["التغير المناخي","تغير طويل المدى في أنماط المناخ."],["الغازات الدفيئة","غازات تحتفظ بجزء من الحرارة في الغلاف الجوي."],["الاحترار العالمي","ارتفاع متوسط حرارة سطح الأرض على المدى الطويل."],["التكيف","إجراءات تساعد الإنسان والنظم على التعامل مع آثار التغير المناخي."],["الانبعاثات","مواد أو غازات تطلق إلى البيئة، ومنها انبعاثات ناتجة عن حرق الوقود."]],"quick":[["ما المقصود بالتغير المناخي؟","تغير طويل المدى في أنماط المناخ مثل الحرارة والأمطار."],["ما علاقة الغازات الدفيئة بالاحترار؟","احتفاظها بالحرارة في الغلاف الجوي يساهم في زيادة الاحترار."],["اذكر أثرًا بيئيًا.","تغير توافر المياه أو مواطن النباتات والحيوانات."],["ما معنى التكيف؟","إجراءات للتعامل مع الآثار وتقليل أضرارها."],["اذكر سلوكين للفرد.","ترشيد الطاقة والمياه وتقليل الهدر وزراعة الأشجار وغيرها."]],"exam":[["mc","التغير المناخي هو...",["تغير طويل المدى في أنماط المناخ","تغير يومي عابر فقط","تغير في أسماء المدن","تغير في اللغات"],0],["tf","الأنشطة البشرية يمكن أن تزيد من انبعاثات الغازات الدفيئة.",["صح","خطأ"],0],["mc","من آثار التغير المناخي المحتملة...",["تغير الأمطار والجفاف وموجات الحرارة","ثبات المناخ دائمًا","اختفاء المياه من الأرض كلها","إلغاء الفصول في كل مكان"],0],["tf","يمكن أن تتأثر النباتات والحيوانات بتغير المناخ.",["صح","خطأ"],0],["mc","أي مجال بشري قد يتأثر؟",["الزراعة والموارد المائية","الأسماء فقط","اللغة فقط","ألوان الملابس"],0],["tf","التكيف يعني تجاهل الآثار المناخية.",["صح","خطأ"],1],["mc","من وسائل التكيف...",["تحسين إدارة المياه والاستعداد للمخاطر","زيادة الهدر","إهمال التحذيرات","تدمير الغطاء النباتي"],0],["tf","ترشيد استهلاك الطاقة والمياه سلوك إيجابي.",["صح","خطأ"],0],["mc","ما المصدر الرئيسي لزيادة الغازات الدفيئة من الأنشطة البشرية؟",["حرق الوقود الأحفوري في أنشطة كثيرة","زراعة الأشجار","ترشيد المياه","إعادة الاستخدام"],0],["tf","تختلف آثار التغير المناخي من مكان إلى آخر.",["صح","خطأ"],0],["mc","ما أفضل وصف لدور الفرد؟",["تقليل الهدر وترشيد الموارد والمشاركة في الحماية","لا دور له مطلقًا","حل المشكلة وحده دون مؤسسات","زيادة استهلاك الطاقة"],0],["tf","مواجهة التغير المناخي تحتاج إلى تعاون الأفراد والمؤسسات والدول.",["صح","خطأ"],0],["mc","ما الذي يمكن أن يساهم في خفض الانبعاثات؟",["تقليل استهلاك الطاقة الملوثة وزيادة الكفاءة","زيادة حرق الوقود","إهدار الطاقة","إزالة الأشجار"],0],["mc","أي عبارة تفرق بين التخفيف والتكيف؟",["التخفيف يقلل الأسباب، والتكيف يتعامل مع الآثار","كلاهما يعني تجاهل المشكلة","التكيف يزيد الانبعاثات","التخفيف يعني زيادة الهدر"],0],["tf","زراعة الأشجار وحماية المساحات الخضراء يمكن أن تكون جزءًا من السلوك البيئي.",["صح","خطأ"],0]]},{"id":"lesson10","number":10,"title":"الثورة العرابية وبداية الاحتلال البريطاني لمصر","subtitle":"أسباب الثورة العرابية وأحداثها والاحتلال البريطاني سنة 1882م.","intro":"يفسر الدرس أسباب الثورة العرابية وتطور أحداثها ثم وصول بريطانيا إلى احتلال مصر.","keyIdea":"الثورة العرابية ارتبطت بمطالب سياسية وعسكرية ووطنية، وانتهت بهزيمة الحركة ووقوع الاحتلال البريطاني.","visual":"🇪🇬","visualText":"خط زمني تفاعلي: أسباب → الثورة → التل الكبير → الاحتلال 1882م.","parts":[["الجزء الأول: أسباب الثورة",["ظهرت الثورة العرابية في ظل مشكلات سياسية ومالية وتدخل أجنبي وتذمر داخل الجيش من التمييز وبعض الأوضاع المرتبطة بالسلطة.","تبلورت مطالب تتعلق بالإصلاح وتقوية مجلس النواب والحد من الاستبداد والتدخل الأجنبي، وتحولت المطالب إلى حركة واسعة."]],["الجزء الثاني: تطور الثورة",["ارتبطت الثورة بأحمد عرابي وعدد من الضباط، وبرزت مطالبهم في مواقف ولقاءات سياسية وعسكرية، ثم دخلت البلاد في صراع مع الخديو توفيق والقوى الأجنبية.","استغلت بريطانيا وفرنسا اضطراب الأوضاع للضغط والتدخل، ثم اتجهت بريطانيا إلى العمل العسكري المباشر."]],["الجزء الثالث: المواجهة العسكرية",["وقعت معارك بين القوات المصرية والبريطانية، ومن أبرز محطات الأحداث معركة التل الكبير التي انتهت بهزيمة القوات العرابية.","أدت الهزيمة إلى انهيار المقاومة المنظمة في تلك المرحلة، وأصبح الطريق مفتوحًا أمام السيطرة البريطانية على مصر."]],["الجزء الرابع: الاحتلال البريطاني",["دخلت القوات البريطانية القاهرة وبدأ الاحتلال سنة 1882م، وأصبحت مصر تحت السيطرة البريطانية مع بقاء ارتباطها الرسمي بالدولة العثمانية في البداية.","يُفهم الاحتلال في سياق طويل من التدخل الأجنبي والأزمات المالية والسياسية، ولذلك تمثل الثورة العرابية محطة مهمة في تاريخ الحركة الوطنية المصرية."]]],"terms":[["الثورة العرابية","حركة وطنية وعسكرية في مصر ارتبطت بأحمد عرابي ومطالب الإصلاح."],["أحمد عرابي","أحد أبرز قادة الثورة العرابية."],["التل الكبير","موقع معركة مهمة انتهت بهزيمة القوات العرابية أمام البريطانيين."],["الاحتلال البريطاني","سيطرة بريطانيا على مصر منذ 1882م."],["التدخل الأجنبي","تدخل قوى خارجية في الشؤون السياسية والمالية المصرية."]],"quick":[["اذكر بعض أسباب الثورة العرابية.","مشكلات سياسية ومالية، وتدخل أجنبي، وتذمر داخل الجيش ومطالب بالإصلاح."],["من أبرز قادة الثورة؟","أحمد عرابي."],["ما المعركة الحاسمة؟","معركة التل الكبير."],["متى بدأ الاحتلال البريطاني؟","سنة 1882م."],["كيف ترتبط الثورة بالاحتلال؟","هزيمة الثورة عسكريًا ساعدت على فتح الطريق أمام السيطرة البريطانية."]],"exam":[["mc","من أبرز قادة الثورة العرابية؟",["أحمد عرابي","مصطفى كامل","محمد فريد","محمد علي"],0],["tf","ارتبطت الثورة العرابية بمطالب إصلاحية ووطنية.",["صح","خطأ"],0],["mc","من أسباب الثورة...",["التدخل الأجنبي ومشكلات سياسية وعسكرية","زيادة الاستقلال الكامل","اختفاء الأزمات","إلغاء الجيش"],0],["tf","كان للجيش جانب من أسباب التذمر الذي ظهر قبل الثورة.",["صح","خطأ"],0],["mc","ما الموقع المرتبط بالمعركة الحاسمة؟",["التل الكبير","الإسكندرية فقط","القاهرة فقط","السويس فقط"],0],["tf","انتهت معركة التل الكبير بانتصار القوات العرابية.",["صح","خطأ"],1],["mc","متى بدأ الاحتلال البريطاني لمصر؟",["1882م","1805م","1840م","1919م"],0],["tf","سبق الاحتلال البريطاني تدخل أجنبي وأزمات سياسية ومالية.",["صح","خطأ"],0],["mc","من المطالب المرتبطة بالحركة العرابية...",["الإصلاح والحد من الاستبداد والتدخل الأجنبي","إلغاء الإصلاح","زيادة التدخل الأجنبي","منع مجلس النواب"],0],["tf","أدت هزيمة القوات العرابية إلى إضعاف المقاومة المنظمة.",["صح","خطأ"],0],["mc","ما نتيجة الأحداث العسكرية سنة 1882م؟",["وقوع مصر تحت الاحتلال البريطاني","خروج بريطانيا","استقلال كامل","إلغاء التدخل"],0],["tf","كانت الثورة العرابية محطة في تاريخ الحركة الوطنية المصرية.",["صح","خطأ"],0],["mc","ما العلاقة بين الأزمة المالية والتدخل الأجنبي؟",["الأزمة زادت فرص الضغط والتدخل الخارجي","الأزمة ألغت التدخل","لا علاقة","الأزمة أنهت الديون فورًا"],0],["mc","أي ترتيب أقرب لأحداث الدرس؟",["مطالب وأسباب → ثورة → التل الكبير → الاحتلال","احتلال → ثورة → إصلاح","ثورة → محمد علي → الاحتلال","ديون → استقلال → ثورة"],0],["tf","ظل الوجود البريطاني بعد 1882م جزءًا من تاريخ مصر الحديث والحركة الوطنية.",["صح","خطأ"],0]]},{"id":"lesson11","number":11,"title":"كفاح الحركة الوطنية وبناء الوعي الوطني (مصطفى كامل ومحمد فريد)","subtitle":"مصطفى كامل ومحمد فريد ودور الصحافة والتعليم والوعي الوطني.","intro":"يتناول الدرس استمرار الكفاح الوطني بعد الاحتلال ودور مصطفى كامل ومحمد فريد في نشر الوعي والدفاع عن الاستقلال.","keyIdea":"بناء الوعي الوطني يعتمد على التعليم والصحافة والعمل السياسي والصمود، وليس على المواجهة العسكرية وحدها.","visual":"📰","visualText":"خريطة تفاعلية: الصحافة + التعليم + التنظيم السياسي + الوعي الوطني.","parts":[["الجزء الأول: مصطفى كامل",["ظهر مصطفى كامل كأحد أبرز قادة الحركة الوطنية، وركز على الدفاع عن استقلال مصر ومقاومة الاحتلال وكشف آثاره أمام الرأي العام.","استخدم الخطابة والكتابة والصحافة في نشر الأفكار الوطنية، وسعى إلى توسيع الوعي بالقضية المصرية داخليًا وخارجيًا."]],["الجزء الثاني: الصحافة والإعلام",["أصبحت الصحافة وسيلة مهمة لنشر الأخبار والأفكار ومناقشة قضايا الوطن، وساعدت الصحف الوطنية في تكوين رأي عام أكثر وعيًا بالاحتلال ومشكلاته.","ارتبط العمل الصحفي بالقدرة على مخاطبة شرائح مختلفة من المجتمع، ولذلك كان الإعلام جزءًا من أدوات الحركة الوطنية."]],["الجزء الثالث: محمد فريد",["واصل محمد فريد العمل الوطني بعد مصطفى كامل، واهتم بالتنظيم السياسي ونشر الوعي والمطالبة بالإصلاح والاستقلال.","كان التعليم والعمل العام من الوسائل التي ارتبطت ببناء مجتمع أكثر قدرة على فهم حقوقه والدفاع عنها، كما ركزت الحركة على الاستمرار رغم صعوبة الظروف."]],["الجزء الرابع: بناء الوعي والصمود",["الحركة الوطنية لم تعتمد على شخصية واحدة؛ بل تضافرت فيها جهود القادة والصحافة والتعليم والعمل السياسي. وكان الهدف بناء وعي عام يجعل قضية الاستقلال قضية مجتمع.","يعلمنا هذا الدرس أن الصمود والمثابرة والعمل المنظم عناصر أساسية في الكفاح الوطني، وأن بناء الوعي يحتاج إلى وقت واستمرار."]]],"terms":[["مصطفى كامل","قائد وطني ركز على الاستقلال ومقاومة الاحتلال وبناء الوعي."],["محمد فريد","قائد وطني واصل الكفاح واهتم بالتنظيم والوعي والتعليم."],["الحركة الوطنية","جهود سياسية وفكرية ومجتمعية لمقاومة الاحتلال والمطالبة بالاستقلال."],["الوعي الوطني","إدراك المجتمع لقضايا الوطن وحقوقه وضرورة الدفاع عنها."],["الصحافة الوطنية","صحافة تستخدم في نشر الأفكار والقضايا الوطنية وتكوين الرأي العام."]],"quick":[["ما دور مصطفى كامل؟","نشر الوعي والدفاع عن الاستقلال ومقاومة الاحتلال بالعمل السياسي والصحفي."],["ما أهمية الصحافة؟","نشر الأفكار وتكوين رأي عام واعٍ بالقضايا الوطنية."],["من واصل الكفاح بعد مصطفى كامل؟","محمد فريد."],["ما دور التعليم؟","يساعد على بناء وعي المجتمع وفهم الحقوق والقضايا العامة."],["ما معنى الصمود في الحركة الوطنية؟","الاستمرار في العمل رغم الصعوبات وعدم التخلي عن الهدف الوطني."]],"exam":[["mc","من أبرز قادة الحركة الوطنية بعد الاحتلال؟",["مصطفى كامل ومحمد فريد","محمد علي فقط","أحمد عرابي فقط","نابليون"],0],["tf","استخدم مصطفى كامل الصحافة والخطابة في العمل الوطني.",["صح","خطأ"],0],["mc","ما هدف الحركة الوطنية؟",["مقاومة الاحتلال وبناء الوعي والمطالبة بالاستقلال","زيادة الاحتلال","إلغاء التعليم","منع الصحافة"],0],["tf","يمكن للصحافة أن تسهم في تكوين الرأي العام.",["صح","خطأ"],0],["mc","من الوسائل التي اعتمدت عليها الحركة الوطنية...",["التعليم والصحافة والعمل السياسي","الترفيه فقط","إهمال المجتمع","إلغاء التنظيم"],0],["tf","واصل محمد فريد الكفاح الوطني بعد مصطفى كامل.",["صح","خطأ"],0],["mc","ماذا يعني الوعي الوطني؟",["إدراك قضايا الوطن وحقوقه","حفظ أسماء المدن","معرفة الأسعار فقط","تجاهل الاحتلال"],0],["tf","التعليم يمكن أن يساعد في بناء الوعي.",["صح","خطأ"],0],["mc","لماذا كانت الصحافة مهمة؟",["لنشر الأفكار وتكوين رأي عام","لمنع المعلومات","لإيقاف التعليم","لزيادة الأمية"],0],["tf","الحركة الوطنية اعتمدت على العمل المنظم والمثابرة.",["صح","خطأ"],0],["mc","أي عبارة تصف محمد فريد؟",["واصل الكفاح الوطني واهتم بالتنظيم والوعي","قاد الحملة الفرنسية","تولى حكم مصر سنة 1805","قاد الاحتلال البريطاني"],0],["tf","كان هدف بناء الوعي جعل قضية الاستقلال قضية مجتمع.",["صح","خطأ"],0],["mc","ما العلاقة بين التعليم والاستقلال؟",["التعليم يساعد المجتمع على فهم حقوقه وقضاياه","التعليم يمنع الوعي","لا علاقة مطلقًا","التعليم يزيد الاحتلال"],0],["mc","ما أفضل وسيلة لفهم نجاح الحركة الوطنية؟",["تضافر القادة والصحافة والتعليم والتنظيم","شخص واحد فقط","المواجهة العسكرية وحدها","إهمال المجتمع"],0],["tf","الصمود يعني الاستمرار في العمل رغم الصعوبات.",["صح","خطأ"],0]]}];
const ACH=[['first','🌱','البداية','أنهيت أول درس.'],['five','🔥','نصف الطريق','اجتزت 5 دروس.'],['unit','📚','وحدة كاملة','أكملت وحدة دراسية.'],['all','🏆','المتفوق','أكملت المنهج كاملًا.']];
let state,currentLesson=null,currentExam=null,lastExam=null,answers=[],questionIndex=0,utterance=null,speechMap=[],speechWordSpans=[],speechText='';
const lessons=()=>CURRICULUM.flatMap(u=>u.lessons.map(l=>({...l,unitNumber:u.number,unitTitle:u.title})));
const lesson=id=>lessons().find(l=>l.id===id);
const indexOfLesson=id=>lessons().findIndex(l=>l.id===id);
const clamp=n=>Math.max(0,Math.min(100,Number(n)||0));
const pct=(a,b)=>Math.round((a/b)*100);
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function initialState(){return {studentName:'الطالب',unlockedLessons:1,completedLessons:[],lessonProgress:{},exams:[],achievements:[]};}
function load(){try{state=JSON.parse(localStorage.getItem(APP.storageKey))||initialState();}catch(e){state=initialState();} state.lessonProgress=state.lessonProgress||{};state.completedLessons=state.completedLessons||[];state.exams=state.exams||[];state.unlockedLessons=Math.max(1,Math.min(APP.totalLessons,Number(state.unlockedLessons)||1));}
function save(){localStorage.setItem(APP.storageKey,JSON.stringify(state));}
function showScreen(id){$$('.screen').forEach(s=>s.classList.remove('active','active-screen'));const el=$(id);if(el)el.classList.add('active-screen');window.scrollTo(0,0);closeMenu();renderHome();}
function toast(msg,type='success'){const box=$('toastContainer');if(!box)return;const el=document.createElement('div');el.className='toast '+type;el.textContent=msg;box.appendChild(el);setTimeout(()=>el.remove(),3200);}
function progress(el,p){if(el)el.style.width=clamp(p)+'%';}
function contentPct(){return Math.round(lessons().reduce((a,l)=>a+clamp(state.lessonProgress[l.id]||0),0)/(APP.totalLessons));}
function bookPct(){return Math.round(state.completedLessons.length/APP.totalLessons*100);}
function avg(){if(!state.exams.length)return 0;return Math.round(state.exams.reduce((a,e)=>a+e.percentage,0)/state.exams.length);}
function level(){const a=avg();return a>=85?['ممتاز','أداء رائع — استمر بنفس القوة!']:a>=65?['جيد جدًا','أنت على الطريق الصحيح، واصل المراجعة.']:a>=50?['جيد','تحتاج إلى تثبيت بعض النقاط.']:['ضعيف','راجع الدروس والأخطاء ثم أعد المحاولة.'];}
function dashboard(){const [lv,desc]=level();const cp=contentPct(),bp=bookPct();$('dashboardContentPercent').textContent=cp+'%';$('dashboardBookPercent').textContent=bp+'%';$('dashboardAverage').textContent=avg()+'%';$('dashboardLevel').textContent=lv;$('levelName').textContent=lv;$('levelDescription').textContent=desc;$('levelProgressCircle').style.setProperty('--progress',avg()+'%');$('completedLessonsCount').textContent=state.completedLessons.length;$('completedExamsCount').textContent=state.exams.length;$('unlockedLessonsCount').textContent=state.unlockedLessons;progress($('contentProgressFill'),cp);progress($('bookProgressFill'),bp);$('contentProgressText').textContent=cp+'%';$('bookProgressText').textContent=bp+'%';$('averageScore').textContent=avg()+'%';}
function renderHomeUnits(){$('homeUnitsGrid').innerHTML=CURRICULUM.map(u=>`<article class="unit-mini-card"><span>الوحدة ${u.number}</span><h3>${esc(u.title)}</h3><p>${u.lessons.length} دروس</p></article>`).join('');}
function renderHome(){if(!$('homeScreen'))return;dashboard();const l=lessons()[Math.min(state.unlockedLessons-1,APP.totalLessons-1)];if(l){const p=clamp(state.lessonProgress[l.id]||0);$('currentLessonTitle').textContent=l.title;$('currentLessonDescription').textContent=l.subtitle;$('currentLessonProgressText').textContent=p+'%';progress($('currentLessonProgressBar'),p);$('currentLessonStatus').textContent=state.completedLessons.includes(l.id)?'✅ مكتمل':'🔓 متاح';$('continueLessonButton').textContent=state.completedLessons.includes(l.id)?'🔎 مراجعة الدرس':p?'▶️ استكمال المذاكرة':'🚀 ابدأ المذاكرة';}const m=['أنت تقدر! 🌟','ركز في الفكرة ثم اختبر نفسك. 💪','الاستمرار يصنع الفرق. 🚀','راجع أخطاءك وستتحسن. 🧠'];$('motivationMessage').textContent=m[state.exams.length%m.length];const last=state.exams.at(-1);$('recentExamContent').innerHTML=last?`<div class="exam-history-card"><strong>${esc(last.lessonTitle)}</strong><span>${last.score}/${last.total} — ${last.percentage}%</span></div>`:'<div class="empty-state"><span>📝</span><h3>لسه مفيش اختبارات</h3><p>ابدأ أول درس.</p></div>';renderHomeUnits();}
function renderUnits(){$('unitsFullGrid').innerHTML=CURRICULUM.map(u=>{const done=u.lessons.filter(l=>state.completedLessons.includes(l.id)).length;const p=pct(done,u.lessons.length);return`<article class="unit-card"><span class="unit-number">الوحدة ${u.number}</span><h3>${esc(u.title)}</h3><p>${esc(u.type||'دراسات اجتماعية')}</p><div class="progress-label"><span>${done}/${u.lessons.length} مكتملة</span><strong>${p}%</strong></div><div class="progress-track"><div class="progress-fill" style="width:${p}%"></div></div><div class="lesson-list">${u.lessons.map(l=>{const i=indexOfLesson(l.id),ok=i<state.unlockedLessons,done=state.completedLessons.includes(l.id),lp=clamp(state.lessonProgress[l.id]||0);return`<button class="lesson-item ${ok?'':'locked'}" data-lesson-id="${l.id}" ${ok?'':'disabled'}><span>${done?'✅':ok?'📖':'🔒'}</span><span style="flex:1;text-align:right"><strong>${esc(l.title)}</strong><small style="display:block">${ok?'تقدم '+lp+'%':'مغلق حتى اجتياز السابق بنسبة 65%'}</small></span><span>›</span></button>`}).join('')}</div></article>`}).join('');$$('[data-lesson-id]').forEach(b=>b.onclick=()=>openLesson(b.dataset.lessonId));}
function openLesson(id){const i=indexOfLesson(id);if(i<0)return;if(i>=state.unlockedLessons){toast('الدرس مقفول. اجتز الاختبار السابق بنسبة 65%.','warning');return;}currentLesson=lesson(id);state.lessonProgress[id]=clamp(state.lessonProgress[id]||0);save();renderLesson();showScreen('lessonScreen');}
function renderLesson(){if(!currentLesson)return;$('lessonUnitIndicator').textContent=`الوحدة ${currentLesson.unitNumber}: ${currentLesson.unitTitle}`;$('lessonNumber').textContent='الدرس '+currentLesson.number;$('lessonTitle').textContent=currentLesson.title;$('lessonSubtitle').textContent=currentLesson.subtitle;$('lessonIntroText').textContent=currentLesson.intro;$('lessonKeyIdeaText').textContent=currentLesson.keyIdea;
$('lessonContent').innerHTML=currentLesson.parts.map((part,idx)=>`<section class="lesson-part" data-part="${idx+1}"><div class="part-head"><span>الجزء ${idx+1} من 4</span><h2>${esc(part[0])}</h2></div>${part[1].map((p,j)=>`<p class="lesson-paragraph">${highlightText(p)}</p>`).join('')}<div class="focus-box"><strong>🎯 ركّز:</strong> ${esc(currentLesson.quick[Math.min(idx,currentLesson.quick.length-1)][0])}</div><button type="button" class="part-complete-button" data-part-complete="${idx+1}">✅ نهاية الجزء ${idx+1}</button></section>`).join('');
$('interactiveVisual').innerHTML=`<div class="interactive-card" style="text-align:center;padding:25px"><div style="font-size:65px">${currentLesson.visual}</div><h3>${esc(currentLesson.title)}</h3><p>${esc(currentLesson.visualText)}</p><button id="visualInfoButton" class="secondary-button" type="button">💡 معلومة تفاعلية</button></div>`;$('visualInfoButton').onclick=()=>toast('اربط بين الفكرة والخريطة/المخطط ثم أكمل الجزء الحالي.','success');
$('importantTermsList').innerHTML=currentLesson.terms.map(t=>`<article class="term-card"><strong>${esc(t[0])}</strong><p>${esc(t[1])}</p></article>`).join('');$('importantPointsList').innerHTML=currentLesson.quick.map(q=>`<li><strong>${esc(q[0])}</strong><br>${esc(q[1])}</li>`).join('');$('quickReviewQuestions').innerHTML=currentLesson.quick.map((q,i)=>`<div class="review-question quick-answer"><strong>سؤال ${i+1}: ${esc(q[0])}</strong><p>✅ الإجابة: ${esc(q[1])}</p></div>`).join('');$('startLessonExamButton').textContent=state.completedLessons.includes(currentLesson.id)?'🔄 إعادة اختبار الدرس':'📝 ابدأ اختبار الدرس';$('startLessonExamButton').disabled=clamp(state.lessonProgress[currentLesson.id]||0)<100;bindParts();}
function highlightText(t){let s=esc(t);s=s.replace(/(الموقع الجغرافي|التضاريس|قارات العالم الجديد|المايا|الأزتك|الإنكا|الكشوف الجغرافية|محمد علي|الاحتكار|أزمة الديون|التغير المناخي|الثورة العرابية|مصطفى كامل|محمد فريد|الاحتلال البريطاني|التيارات البحرية)/g,'<mark class="keyword-highlight">$1</mark>');return s;}
function bindParts(){const current=clamp(state.lessonProgress[currentLesson.id]||0);const doneParts=Math.floor(current/25);$$('[data-part-complete]').forEach(b=>{const n=Number(b.dataset.partComplete);b.disabled=n<=doneParts||n!==doneParts+1;b.onclick=()=>{if(n!==doneParts+1)return;state.lessonProgress[currentLesson.id]=n*25;save();renderLesson();if(n===4){toast('ممتاز! خلصت الدرس بالكامل، والاختبار اتفتح لك. 🎉','success');$('startLessonExamButton').disabled=false;}else toast(`تم إنهاء الجزء ${n}. كمل الجزء اللي بعده! 💪`,'success');};});}
function startExam(id=currentLesson?.id){examQuestions=[];const l=lesson(id);if(!l)return;const i=indexOfLesson(id);if(i>=state.unlockedLessons){toast('الاختبار مقفول.','warning');return;}if(clamp(state.lessonProgress[id]||0)<100){toast('لازم تخلص الأجزاء الأربعة الأول.','warning');return;}currentLesson=l;currentExam={id:`exam_${id}_${Date.now()}`,lessonId:id,lessonTitle:l.title,unitTitle:l.unitTitle,total:15,startedAt:new Date().toISOString()};answers=Array(15).fill(null);questionIndex=0;renderQuestion();showScreen('examScreen');}
function questionPool(l){return l.exam.map(q=>{let [type,text,opts,ans]=q;let o=[...opts],a=ans;for(let i=o.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[o[i],o[j]]=[o[j],o[i]];}a=o.indexOf(opts[ans]);return {type,text,options:o,answer:a};});}
let examQuestions=[];
function renderQuestion(){if(!currentLesson)return;if(!examQuestions.length)examQuestions=questionPool(currentLesson);const q=examQuestions[questionIndex];$('examQuestionNumber').textContent=(questionIndex+1)+' / 15';$('examTitle').textContent='اختبار: '+currentLesson.title;$('examUnitName').textContent=currentLesson.unitTitle;$('examProgressText').textContent=Math.round((questionIndex+1)/15*100)+'%';progress($('examProgressBar'),(questionIndex+1)/15*100);$('examQuestionsContainer').innerHTML=`<article class="question-card"><span class="question-type">${q.type==='mc'?'اختيار من متعدد':'صح أو خطأ'}</span><h2>${esc(q.text)}</h2><div class="answers-grid">${q.options.map((o,i)=>`<button class="answer-option ${answers[questionIndex]===i?'selected':''}" data-answer="${i}">${esc(o)}</button>`).join('')}</div></article>`;$$('[data-answer]').forEach(b=>b.onclick=()=>{answers[questionIndex]=Number(b.dataset.answer);renderQuestion();});$('previousQuestionButton').disabled=questionIndex===0;$('nextQuestionButton').style.display=questionIndex===14?'none':'';$('submitExamButton').style.display=questionIndex===14?'':'none';}
function nextQ(){if(answers[questionIndex]===null){toast('اختار إجابة الأول 😊','warning');return;}questionIndex++;renderQuestion();}
function prevQ(){if(questionIndex>0){questionIndex--;renderQuestion();}}
function submitExam(){if(answers.some(a=>a===null)){toast('جاوب كل الأسئلة قبل الإنهاء.','warning');return;}let score=0;examQuestions.forEach((q,i)=>{if(answers[i]===q.answer)score++;});const p=pct(score,15),passed=p>=APP.passPercent;const ex={...currentExam,finishedAt:new Date().toISOString(),score,total:15,percentage:p,passed,answers:[...answers],correctAnswers:examQuestions.map(q=>q.answer),questions:examQuestions};state.exams.push(ex);lastExam=ex;if(passed){const i=indexOfLesson(currentLesson.id);if(!state.completedLessons.includes(currentLesson.id))state.completedLessons.push(currentLesson.id);state.lessonProgress[currentLesson.id]=100;if(i<APP.totalLessons-1)state.unlockedLessons=Math.max(state.unlockedLessons,i+2);}else state.lessonProgress[currentLesson.id]=Math.min(99,Number(state.lessonProgress[currentLesson.id]||75));save();updateAchievements();renderResult(ex);showScreen('examResultScreen');}
function renderResult(ex){$('resultIcon').textContent=ex.passed?'🎉':'📚';$('resultTitle').textContent=ex.passed?'أحسنت! اجتزت الاختبار':'لسه محتاج مراجعة';$('resultScore').textContent=`${ex.score} / 15`;$('resultPercentage').textContent=ex.percentage+'%';$('resultMessage').textContent=ex.passed?(ex.percentage>=85?'ممتاز جدًا! 🔥':'مبروك! حققت نسبة النجاح وفتحنا الدرس التالي.'):`جبت ${ex.percentage}%، والمطلوب ${APP.passPercent}% على الأقل. راجع الدرس وحاول تاني.`;$('nextLessonButton').style.display=ex.passed&&indexOfLesson(ex.lessonId)<APP.totalLessons-1?'':'none';}
function review(ex=lastExam){if(!ex){toast('لا يوجد اختبار للمراجعة.','warning');return;}$('reviewTitle').textContent='مراجعة: '+ex.lessonTitle;$('reviewSummary').innerHTML=`<h2>${ex.score}/15 — ${ex.percentage}%</h2><p>${ex.passed?'راجع إجاباتك للتثبيت.':'راجع الأخطاء ثم أعد الاختبار.'}</p>`;$('reviewQuestionsContainer').innerHTML=ex.questions.map((q,i)=>{const ua=ex.answers[i],ok=ua===q.answer;return`<article class="review-question ${ok?'correct':'wrong'}"><strong>السؤال ${i+1}</strong><p>${esc(q.text)}</p><p>إجابتك: ${esc(q.options[ua]??'بدون إجابة')}</p><p><strong>الإجابة الصحيحة: ${esc(q.options[q.answer])}</strong></p></article>`}).join('');showScreen('reviewScreen');}
function renderHistory(){$('examsSummary').innerHTML=`<article class="exam-summary-card"><strong>${state.exams.length}</strong><span>إجمالي الاختبارات</span></article><article class="exam-summary-card"><strong>${state.exams.filter(e=>e.passed).length}</strong><span>مجتازة</span></article><article class="exam-summary-card"><strong>${avg()}%</strong><span>المتوسط</span></article>`;if(!state.exams.length){$('examsHistoryList').innerHTML='<div class="empty-state"><span>📝</span><h3>لا توجد اختبارات</h3></div>';return;}$('examsHistoryList').innerHTML=[...state.exams].reverse().map(e=>`<article class="exam-history-card"><div><strong>${esc(e.lessonTitle)}</strong><span style="display:block">${e.score}/15 — ${e.percentage}%</span><small>${new Date(e.finishedAt).toLocaleString('ar-EG')}</small></div><button class="secondary-button" data-history="${e.id}">مراجعة</button></article>`).join('');$$('[data-history]').forEach(b=>b.onclick=()=>review(state.exams.find(e=>e.id===b.dataset.history)));}
function renderProgress(){$('progressUnitsList').innerHTML=CURRICULUM.map(u=>`<article class="progress-unit-card"><h2>الوحدة ${u.number}: ${esc(u.title)}</h2>${u.lessons.map(l=>`<div class="lesson-item"><span>${state.completedLessons.includes(l.id)?'✅':'📖'}</span><strong style="flex:1">${esc(l.title)}</strong><span>${clamp(state.lessonProgress[l.id]||0)}%</span></div>`).join('')}</article>`).join('');dashboard();}
function updateAchievements(){const s=new Set(state.achievements||[]);if(state.completedLessons.length>=1)s.add('first');if(state.completedLessons.length>=5)s.add('five');if(state.completedLessons.filter(id=>id.startsWith('lesson')).length>=3)s.add('unit');if(state.completedLessons.length===APP.totalLessons)s.add('all');state.achievements=[...s];save();}
function renderAchievements(){updateAchievements();$('achievementsGrid').innerHTML=ACH.map(a=>`<article class="achievement-card ${state.achievements.includes(a[0])?'':'locked'}"><div class="achievement-icon">${a[1]}</div><h3>${esc(a[2])}</h3><p>${esc(a[3])}</p><small>${state.achievements.includes(a[0])?'تم الفتح ✅':'مغلق 🔒'}</small></article>`).join('');}
function prepareSpeech(){const box=$('lessonContent');if(!box)return;speechWordSpans=[];speechMap=[];let full='';const walker=document.createTreeWalker(box,NodeFilter.SHOW_TEXT);const nodes=[];let n;while((n=walker.nextNode())){if(n.nodeValue.trim())nodes.push(n);}nodes.forEach(node=>{const text=node.nodeValue,frag=document.createDocumentFragment();let m;const re=/\S+|\s+/g;while((m=re.exec(text))){const part=m[0],span=document.createElement('span');span.textContent=part;if(/\S/.test(part)){span.className='js-speech-word';const start=full.length;full+=part;speechMap.push({start,end:full.length,span});speechWordSpans.push(span);}else full+=part;frag.appendChild(span);}node.parentNode.replaceChild(frag,node);});speechText=full;if(!document.getElementById('speechStyle')){const st=document.createElement('style');st.id='speechStyle';st.textContent='#lessonContent .js-speech-word{border-radius:5px;transition:.12s}#lessonContent .js-speech-active{background:#ffe66d;color:#172033;box-shadow:0 2px 8px rgba(0,0,0,.12)}';document.head.appendChild(st);}}
function clearSpeech(){speechWordSpans.forEach(s=>s.classList.remove('js-speech-active'));}
function speak(){if(!('speechSynthesis'in window)){toast('المتصفح لا يدعم القراءة الصوتية.','warning');return;}if(!currentLesson)return;stopSpeak();prepareSpeech();const txt=[$('lessonTitle').innerText,$('lessonIntroText').innerText,$('lessonKeyIdeaText').innerText,speechText].join('. ');utterance=new SpeechSynthesisUtterance(txt);utterance.lang=APP.speechLanguage;utterance.rate=Number($('readingSpeed').value||.9);utterance.onstart=()=>{$('readLessonButton').disabled=true;$('pauseReadingButton').disabled=false;$('stopReadingButton').disabled=false;$('speechStatus').textContent='🔊 جاري القراءة مع التظليل';};utterance.onboundary=e=>{const i=Math.max(0,e.charIndex-(($('lessonTitle').innerText+' '+$('lessonIntroText').innerText+' '+$('lessonKeyIdeaText').innerText).length+3));clearSpeech();const hit=speechMap.find(x=>i>=x.start&&i<x.end);if(hit){hit.span.classList.add('js-speech-active');hit.span.scrollIntoView({behavior:'smooth',block:'center'});}};utterance.onend=resetSpeech;utterance.onerror=resetSpeech;speechSynthesis.speak(utterance);}
function pauseSpeak(){if(!('speechSynthesis'in window))return;if(speechSynthesis.paused){speechSynthesis.resume();$('pauseReadingButton').textContent='⏸️ إيقاف مؤقت';}else if(speechSynthesis.speaking){speechSynthesis.pause();$('pauseReadingButton').textContent='▶️ متابعة';}}
function stopSpeak(){if('speechSynthesis'in window)speechSynthesis.cancel();resetSpeech();}
function resetSpeech(){$('readLessonButton').disabled=false;$('pauseReadingButton').disabled=true;$('stopReadingButton').disabled=true;$('pauseReadingButton').textContent='⏸️ إيقاف مؤقت';$('speechStatus').textContent='';clearSpeech();}
function openMenu(){$('sideMenu').classList.add('open');$('menuOverlay').classList.add('open');}function closeMenu(){$('sideMenu')?.classList.remove('open');$('menuOverlay')?.classList.remove('open');}
function bind(){$('menuButton').onclick=openMenu;$('closeMenuButton').onclick=closeMenu;$('menuOverlay').onclick=closeMenu;$('homeButton').onclick=()=>showScreen('homeScreen');$$('.navigation-item').forEach(b=>b.onclick=()=>{showScreen(b.dataset.screen);if(b.dataset.screen==='unitsScreen')renderUnits();if(b.dataset.screen==='progressScreen')renderProgress();if(b.dataset.screen==='examsScreen')renderHistory();if(b.dataset.screen==='achievementsScreen')renderAchievements();});$$('[data-screen]').forEach(b=>{if(!b.classList.contains('navigation-item'))b.onclick=()=>{showScreen(b.dataset.screen);if(b.dataset.screen==='unitsScreen')renderUnits();}});$('continueLessonButton').onclick=()=>{const l=lessons()[Math.min(state.unlockedLessons-1,APP.totalLessons-1)];if(l)openLesson(l.id);};$('lessonBackButton').onclick=()=>{stopSpeak();showScreen('unitsScreen');renderUnits();};$('examBackButton').onclick=()=>{showScreen('lessonScreen');renderLesson();};$('startLessonExamButton').onclick=()=>startExam();$('previousQuestionButton').onclick=prevQ;$('nextQuestionButton').onclick=nextQ;$('submitExamButton').onclick=submitExam;$('reviewExamButton').onclick=()=>review(lastExam);$('retryExamButton').onclick=()=>startExam(lastExam?.lessonId);$('nextLessonButton').onclick=()=>{const n=lessons()[indexOfLesson(lastExam.lessonId)+1];if(n)openLesson(n.id);else showScreen('homeScreen');};$('reviewBackButton').onclick=()=>{showScreen('examsScreen');renderHistory();};$('readLessonButton').onclick=speak;$('pauseReadingButton').onclick=pauseSpeak;$('stopReadingButton').onclick=stopSpeak;$('modalCloseButton').onclick=()=>$('modalLayer').classList.remove('open');}
function init(){load();bind();updateAchievements();renderHome();showScreen('homeScreen');}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
